def check_n_detailed(n):
    for k in range(n + 1):
        for m in range(n + 1 - k):
            diff = k - m
            s_min = max(-1, diff - 1)
            s_max = min(1, diff + 1)
            if s_min < s_max:
                s_vals = [s_min, s_max]
                if s_min < diff/2 < s_max:
                    s_vals.append(diff/2)
                f_vals = [2*s**2 - 2*diff*s + (k + m + diff**2) for s in s_vals]
                if min(f_vals) <= 20 <= max(f_vals):
                    print(f"n={n}, k={k}, m={m}, diff={diff}, s_range=({s_min}, {s_max}), f_vals={f_vals}")
                    return True
    return False

for n in range(18, 23):
    check_n_detailed(n)

def check_n_strict(n):
    for k in range(n + 1):
        for m in range(n + 1 - k):
            # Only consider cases where we can actually form a sum S with |S|<1
            # and |S - (k-m)| < 1.
            # Also we want k+m to be as large as possible, so k+m = n or n-1.
            if k + m < n - 1:
                continue

            diff = k - m
            s_min = max(-1, diff - 1)
            s_max = min(1, diff + 1)
            if s_min < s_max:
                # The function is f(S) = (k + m) + (S - diff)**2 + S**2
                # We want to know if there is any S in (s_min, s_max) such that f(S) > 20.
                # This is true if max f(S) on [s_min, s_max] > 20.
                s_vals = [s_min, s_max]
                if s_min < diff/2 < s_max:
                    s_vals.append(diff/2)
                f_vals = [(k + m) + (s - diff)**2 + s**2 for s in s_vals]
                if max(f_vals) > 20:
                    return True
    return False

for n in range(15, 25):
    if check_n_strict(n):
        print(f"n={n} is possible")
